style.css:
@-moz-document domain("elevenlabs.io") {
/* Zmiana tła strony na czarne */
    body {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Zmiana kolorów nagłówków i tekstu */
    h1, h2, h3, h4, h5, h6, p, span, div {
        color: #e0e0e0 !important;
    }

    /* Zmiana tła dla przycisków i inputów */
    button, input, textarea, select {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
        border: 1px solid #333 !important;
    }

    /* Zmiana linków na bardziej widoczne */
    a {
        color: #62dafb !important;
    }

    /* Zmiana kolorów kart, nagłówków i innych elementów */
    .card, .header, .footer, .menu {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
    }

    /* Ukrywanie białych borderów */
    * {
        border-color: #333 !important;
    }
}
